-- Workspaces from before the Audit via AI play get it here; new workspaces get it from SeedDefaults.
INSERT INTO plays (id, workspace_id, label, type, description, instructions, enabled, show_when_stage, excluded_project_ids, created_by, created_at, updated_at, builtin_key)
SELECT lower(hex(randomblob(16))), w.id, 'Audit via AI', 'interview', 'Audits a predecessor''s code, or this project''s own, against the interview memory and writes the findings as a doc.', 'Audit code against this project''s interview memory and write what you find as one doc; the project, today''s date, this run''s trail id, and the code to audit are named below. Start by calling `memory_create` with the project id and `kind` `interview`: it returns the interview memory, whose body is the project''s rules under its headings, with its `answers` and its `sources`. The memory is the yardstick. Check the known breaks first: the answers to follow-ups about what a source under question did, such as one naming how the old project keeps booking state and asking what this one does instead. Then read the code named below: each project source under question through its checkout on this computer, or through its memories and interview answers with `memory_list` and `memory_get` when no checkout is named; with no project source under question, audit this project''s own code in the checkout you are running in. Read selectively: structure, manifests, and config first, then the code each rule speaks to. Write one doc with `doc_create` in this project, without a `folder_id` so it lands in the Main folder, titled Audit of <what you audited>, <today''s date>, such as Audit of Booking app, 2026-10-04. Open its body with one line naming what you audited and this run''s trail id. Group the findings under the memory''s headings, in the memory''s order, one line per finding: its verdict, where it is as `path:line`, and the rule it meets or breaks. A heading with nothing found says so in one line. Auditing a source under question, the verdicts are Carry over (it meets the rule, bring it across), Rebuild (it does a job this project needs but breaks the rule), and Avoid (the rules rule it out). Auditing this project''s own code, they are Keeps (it meets the rule) and Fix (it breaks it). Write a new doc every run, and change no earlier audit, the memory, its answers, or its sources. File no tickets: a person turns the doc into work with To tickets via AI. Never ask the person anything and never use a question tool. End with a one-line summary naming the doc by its title and counting its findings per verdict.', 1, NULL, '[]', '', strftime('%s','now'), strftime('%s','now'), 'audit'
FROM workspaces w
WHERE NOT EXISTS (SELECT 1 FROM plays p WHERE p.workspace_id = w.id AND p.builtin_key = 'audit');
